            _APP_WORKER_PER_CORE: ${_APP_WORKER_PER_CORE:-6}
            SERVICE_FQDN_APPWRITE: /v1
        healthcheck:
            interval: 20s
            retries: 6
            start_period: 120s
            test:
                - CMD-SHELL
                - test -f /tmp/.appwrite-ready && curl -fsS -o /dev/null http://localhost/v1/health/version || exit 1
            timeout: 5s
        image: appwrite/appwrite:2.6.1
        volumes:
            - source: data-appwrite-0
              target: /storage/uploads
              type: volume
            - source: data-appwrite-1
              target: /storage/imports
              type: volume
            - source: data-appwrite-2
              target: /storage/cache
              type: volume
            - source: data-appwrite-3
              target: /storage/config
              type: volume
            - source: data-appwrite-4
              target: /storage/certificates
              type: volume
            - source: data-appwrite-5
              target: /storage/functions
              type: volume
            - source: data-appwrite-6
              target: /storage/sites
              type: volume
            - source: data-appwrite-7
              target: /storage/builds
              type: volume
    appwrite-browser:
        dns:
            - 1.1.1.1
            - 8.8.8.8
        environment:
            ALLOWED_HOSTS: appwrite
        image: appwrite/browser:0.3.6
    appwrite-clickhouse:
        environment:
            CLICKHOUSE_ALWAYS_RUN_INITDB_SCRIPTS: "1"
            CLICKHOUSE_DB: appwrite
            CLICKHOUSE_DEFAULT_ACCESS_MANAGEMENT: "1"
            CLICKHOUSE_PASSWORD: ${SERVICE_PASSWORD_CLICKHOUSE}
            CLICKHOUSE_USER: appwrite
        healthcheck:
            interval: 10s
            retries: 20
            start_period: 30s
            test:
                - CMD-SHELL
                - clickhouse-client --user "$$CLICKHOUSE_USER" --password "$$CLICKHOUSE_PASSWORD" --query "SELECT 1" > /dev/null || exit 1
            timeout: 5s
        image: clickhouse/clickhouse-server:26.4.3-alpine
        ulimits:
            nofile:
                hard: 262144
                soft: 262144
        volumes:
            - source: data-appwrite-clickhouse-0
              target: /var/lib/clickhouse
              type: volume
            - read_only: true
              source: data-appwrite-clickhouse-1
              target: /etc/clickhouse-server/config.d/appwrite.xml
